/* One traceable sample, two methods, one responsible handover. */
(() => {
  'use strict';
  const sheet = document.createElement('link');
  sheet.rel = 'stylesheet';
  sheet.href = new URL('lab.css?v=5', document.currentScript.src).href;
  document.head.append(sheet);
  Object.assign(window.OchakovoShift.roles.lab, {
    lead:'Прими пробу, проведи исследования и помоги команде принять решение по партии.',
    day:'Лаборант регистрирует пробы, готовит их к исследованию, проверяет приборы и сохраняет результаты. Специалист качества оценивает отклонения вместе с технологом и определяет дальнейшие действия.',
    tools:'pH-метр, рефрактометр, контрольные материалы, методики и лабораторный журнал.',
    learned:'Зарегистрировал пробу, измерил pH и °Brix, сохранил исходный и повторный результаты и передал отклонение специалисту качества.'
  });
  window.GameMissions.list.find(item=>item.id==='lab').minutes=10;
  const KEY='ochakovo-lab-episode-v1';
  const phases=['Приёмка','Подготовка','Исследования','Результаты','Проверка','Заключение'];
  const paths={check:'<path d="m5 12 4 4L19 6"/>',arrow:'<path d="M4 12h15m-6-6 6 6-6 6"/>',book:'<path d="M5 3h14v18H5zM9 7h6M9 11h6M9 15h4"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v1"/>',alert:'<path d="m12 3 10 18H2ZM12 9v5m0 3v1"/>',flask:'<path d="M8 3h8m-6 0v7l-6 9a1 1 0 0 0 1 2h14a1 1 0 0 0 1-2l-6-9V3M7 15h10"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',drop:'<path d="M12 2S4 11 4 15a8 8 0 0 0 16 0c0-4-8-13-8-13ZM8 15c0 2 1 3 3 4"/>'};
  const icon=name=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.info}</svg>`;
  const fresh=()=>({version:1,started:false,phase:0,unlocked:0,inspected:[],unknown:'',registered:false,temperature:false,mixed:false,portions:false,controlPh:false,controlBx:false,metric:'ph',phClean:false,phLoaded:false,phRun:false,phSaved:false,bxClean:false,bxLoaded:false,bxRun:false,bxSaved:false,requirement:'',verdictPh:'',verdictBx:'',finding:'',assessed:false,notification:'',messageSent:false,plan:'',reviewed:false,repeatPortion:false,repeatClean:false,repeatRun:false,repeatSaved:false,decision:'',done:false});
  function restore(){
    const state=fresh();
    try{
      const saved=JSON.parse(localStorage.getItem(KEY)||'null');
      if(!saved||saved.version!==1||Array.isArray(saved))return state;
      for(const key of Object.keys(state))if(typeof state[key]==='boolean'&&typeof saved[key]==='boolean')state[key]=saved[key];
      const enums={metric:['ph','bx'],unknown:['','clarify'],requirement:['','base','other'],verdictPh:['','in','below','above'],verdictBx:['','in','below','above'],finding:['','fact','water','ph'],notification:['','facts','vague','blame'],plan:['','review','erase','syrup'],decision:['','hold','release','scrap']};
      Object.entries(enums).forEach(([key,values])=>{if(values.includes(saved[key]))state[key]=saved[key];});
      state.inspected=[...new Set((Array.isArray(saved.inspected)?saved.inspected:[]).filter(v=>['label','direction','seal'].includes(v)))];
      state.unlocked=state.done?5:state.repeatSaved?5:state.assessed?4:state.phSaved&&state.bxSaved?3:state.controlPh&&state.controlBx&&state.portions?2:state.registered?1:0;
      state.phase=Number.isInteger(saved.phase)?Math.max(0,Math.min(saved.phase,state.unlocked)):state.unlocked;
      if(state.done&&(!state.repeatSaved||!state.assessed||!state.messageSent))return fresh();
      return state;
    }catch{return state;}
  }
  function vessel(label='L-041'){
    return `<svg class="lab-vessel" viewBox="0 0 200 260" fill="none" aria-hidden="true"><ellipse cx="100" cy="241" rx="66" ry="9" fill="#dcd7ce"/><path d="M72 36h56v48l28 121c4 17-7 29-24 29H68c-17 0-28-12-24-29L72 84Z" fill="#fff" fill-opacity=".8" stroke="#b7b6ad" stroke-width="2"/><path d="m59 146-15 59c-4 17 7 29 24 29h64c17 0 28-12 24-29l-15-59Z" fill="#dbab52" fill-opacity=".7"/><ellipse cx="100" cy="146" rx="41" ry="6" fill="#edcc84"/><path d="m65 104-22 96M80 49v31" stroke="white" stroke-width="5" stroke-linecap="round"/><rect x="68" y="27" width="64" height="23" rx="5" fill="#c4c5bd"/><path d="M77 30v16m9-16v16m9-16v16m9-16v16m9-16v16m9-16v16" stroke="#a8aca3"/><rect x="52" y="160" width="96" height="49" rx="4" fill="#fffdf9"/><rect x="52" y="160" width="7" height="49" rx="3" fill="#d50032"/><text x="103" y="183" fill="#282724" font-family="inherit" font-size="17" font-weight="600" text-anchor="middle">${label}</text><text x="103" y="199" fill="#69665f" font-family="inherit" font-size="10" text-anchor="middle">P-214 · T-07</text></svg>`;
  }
  function instrument(metric,s,repeat=false){
    const loaded=repeat?s.repeatPortion:s[metric+'Loaded'];
    if(metric==='ph')return `<svg class="lab-device-art lab-ph-art ${loaded?'is-loaded':''}" viewBox="0 0 520 330" fill="none" aria-hidden="true"><ellipse cx="265" cy="295" rx="206" ry="14" fill="#dedbd3"/><path d="m40 230 190-5 40 62H25Z" fill="#e9e6df" stroke="#bbb9b0"/><path d="m40 230 8-68h170l12 63" fill="#fffdf8" stroke="#c6c5bd"/><path d="m67 176-8 42h135l8-42Z" fill="#dfe8dc"/><path d="M79 198h23m8 0h38m10 0h22" stroke="#82947e" stroke-width="3"/><circle cx="69" cy="243" r="7" fill="#d50032"/><circle cx="94" cy="243" r="5" fill="#aaa99f"/><path d="M353 92V280m-34 1h69" stroke="#999e97" stroke-width="10" stroke-linecap="round"/><path d="M353 94h-51v34" stroke="#babeb7" stroke-width="9" stroke-linecap="round"/><path d="M302 126c-45-39-36-85-77-81s-45 69-40 119" stroke="#555e55" stroke-width="5"/><g class="lab-electrode"><rect x="293" y="112" width="18" height="70" rx="6" fill="#4d5950"/><path d="M302 176v63" stroke="#9aa99b" stroke-width="7"/><circle cx="302" cy="241" r="6" fill="#b3bdb2"/></g><path d="m262 204 7 68c1 11 67 11 68 0l7-68" fill="#fff" fill-opacity=".65" stroke="#b2b8ae" stroke-width="2"/><path d="m265 233 4 39c1 11 67 11 68 0l4-39Z" fill="#dfb25e" fill-opacity=".7"/><ellipse cx="303" cy="233" rx="38" ry="5" fill="#edcc84"/><ellipse cx="303" cy="204" rx="42" ry="7" stroke="#aeb6aa" stroke-width="2"/><path d="M278 217v38" stroke="white" stroke-width="4" stroke-linecap="round"/><path d="M387 198h49v62h-49z" fill="#fff" stroke="#c6c9c0"/><path d="M393 229h37v28h-37z" fill="#e4eae0"/><path d="M404 196v-17h19v17" stroke="#a9b5a7" stroke-width="4"/></svg>`;
    return `<svg class="lab-device-art lab-brix-art ${loaded?'is-loaded':''}" viewBox="0 0 520 330" fill="none" aria-hidden="true"><ellipse cx="254" cy="290" rx="190" ry="15" fill="#dedbd3"/><path d="m104 183 273-8 64 95c-34 25-281 27-369 0Z" fill="#dadbd3" stroke="#b4b9ae" stroke-width="2"/><path d="m104 156 247-5 26 24 38 73c-88 21-215 22-329 0Z" fill="#fffefa" stroke="#c8c9bf" stroke-width="2"/><path d="m145 183-9 47 127-1-5-47Z" fill="#dfe8dc" stroke="#c1cbbd"/><path d="M151 206h31m9 0h28m8 0h20" stroke="#82947e" stroke-width="3"/><circle cx="133" cy="249" r="6" fill="#d50032"/><circle cx="153" cy="250" r="4" fill="#aaa99f"/><ellipse cx="320" cy="174" rx="35" ry="16" fill="#7d8a7e"/><ellipse cx="320" cy="170" rx="27" ry="12" fill="#303e34"/><ellipse cx="320" cy="169" rx="19" ry="8" fill="${loaded?'#dca84c':'#c4d1c4'}"/><g class="lab-pipette ${loaded?'has-dispensed':''}"><path d="m355 53-28 70" stroke="#b6bfb3" stroke-width="9"/><path d="m327 123-8 25" stroke="#e9eee5" stroke-width="6"/><path d="m361 37-8 23" stroke="#d50032" stroke-width="18" stroke-linecap="round"/>${loaded?'<path d="M320 150s-6 9-6 12a6 6 0 0 0 12 0c0-3-6-12-6-12" fill="#dca84c"/>':''}</g><path class="lab-light-ray" d="m276 191 44-22 46 18" stroke="#d50032" stroke-width="2" stroke-dasharray="4 4" opacity="${loaded?'.6':'0'}"/><path d="M393 159v34" stroke="#c1c6ba" stroke-width="4"/></svg>`;
  }
  window.OchakovoShift.register('lab',a=>{
    const {esc}=a;
    let s=restore(),message='',kind='neutral',journalOpen=false,tour='',doc='label',hint=0,busy='',liveValue='',storageOK=true,disposed=false;
    const timers=new Set();
    a.root.classList.add('lab-experience');
    a.root.querySelector('.shift-heading').hidden=true;
    a.root.querySelector('.shift-profession').hidden=true;
    const announcer=a.root.querySelector('.shift-feedback');
    announcer.classList.add('lab-announcer');
    const btn=(action,text,cls='',value='',disabled=false)=>a.button(action,text,value,`lab-button ${cls}`,`${disabled?'disabled':''} ${['lab-verdict-ph','lab-verdict-bx'].includes(action)?`aria-pressed="${cls.includes('is-selected')}"`:''}`);
    const primary=(action,text,disabled=false)=>btn(action,text+icon('arrow'),'lab-primary','',disabled);
    const choice=(action,value,title,description='',selected=false)=>`<button type="button" class="lab-choice ${selected?'is-selected':''}" data-do="${action}" data-value="${value}" aria-pressed="${selected}"><span class="lab-choice-mark">${selected?icon('check'):''}</span><span><strong>${title}</strong>${description?`<span>${description}</span>`:''}</span></button>`;
    function save(){try{localStorage.setItem(KEY,JSON.stringify(s));storageOK=true;}catch{storageOK=false;}}
    function tell(text,nextKind='neutral'){message=text;kind=nextKind;announcer.textContent=text;a.say(text,nextKind==='success'?'success':'think');}
    function move(phase){s.phase=phase;s.unlocked=Math.max(s.unlocked,phase);message='';hint=0;save();render();requestAnimationFrame(()=>{if(!disposed)a.content.querySelector('.lab-stage-title')?.focus({preventScroll:true});});a.root.scrollIntoView({block:'start',behavior:'instant'});}
    const prepared=()=>s.temperature&&s.mixed&&s.portions&&s.controlPh&&s.controlBx;
    const receiptReady=()=>s.inspected.length===3&&s.unknown==='clarify';
    const valueFor=metric=>metric==='ph'?'3,21':'9,2';
    const labelFor=metric=>metric==='ph'?'pH':'°Brix';
    function mentor(text,role='Лаборант-наставник'){return `<div class="lab-mentor">${role==='Огонёк'?'<img class="lab-kaplya-avatar" src="assets/lab-guide-illustrated.png" alt="" width="46" height="56">':`<span class="lab-person" aria-hidden="true">${role==='Технолог'?'Т':role==='Специалист качества'?'К':'Л'}</span>`}<div><strong>${role}</strong><p>${text}</p></div></div>`;}
    function note(){return `<div class="lab-inline-note ${kind==='error'?'is-error':kind==='success'?'is-success':''}">${message?icon(kind==='error'?'info':'check')+`<p>${esc(message)}</p>`:''}</div>`;}
    function help(){
      const tips=[['Проверь, что связывает ёмкость с направлением.','Открой этикетку, направление и осмотр крышки. Для второй пробы запроси источник, затем зарегистрируй L-041.'],['Прибору нужна подготовленная проба, а тебе — проверенный прибор.','По учебной методике нужна температура 19–21 °C. Подготовь пробу и порции, затем проверь оба контрольных материала.'],['Сначала подготовка, затем измерение и сохранение.','Для каждого прибора подготовь поверхность или электрод, установи свою порцию и дождись стабильного результата. Сохрани оба показателя.'],['Сравни каждое число с его диапазоном.','3,21 находится между 3,00 и 3,40; 9,2 ниже нижней границы 9,8. Это факт отклонения, его причина ещё неизвестна.'],['Команде нужны факты, а исходному результату — сохранность.','Передай партию, источник и значения. Выбери проверку условий и повтор на новой порции, подготовь прибор и сохрани повтор отдельной строкой.'],['Кто имеет право принять решение по партии?','Передай результаты специалисту качества. Подтверждённое отклонение сохраняется, поэтому удержание партии продолжается.']][s.phase];
      return `<div class="lab-help">${btn('lab-hint',icon('info')+'Подсказка','lab-quiet')}${hint?`<p>${tips[Math.min(hint-1,1)]}</p>`:''}<span class="lab-save-note">${storageOK?'Прогресс сохраняется на этом устройстве':'Сохранение недоступно — не закрывай страницу'}</span></div>`;
    }
    function journal(){return `<section class="lab-journal" aria-label="Лабораторный журнал"><div class="lab-section-row"><h3>Лабораторный журнал</h3><span>L-041 · P-214</span></div><div class="lab-journal-row lab-journal-head"><span>Исследование</span><span>Результат</span><span>Запись</span></div>${[['pH',s.phSaved?'3,21':'—',s.phSaved?'Сохранено':'Ещё не измерено'],['°Brix',s.bxSaved?'9,2 °Bx':'—',s.bxSaved?'Исходный результат':'Ещё не измерено'],...(s.repeatSaved?[['°Brix · повтор','9,2 °Bx','Отдельная запись']]:[])].map(row=>`<div class="lab-journal-row"><strong>${row[0]}</strong><span class="lab-num">${row[1]}</span><span>${row[2]}</span></div>`).join('')}<p class="lab-caption">${s.registered?'Источник: ёмкость T-07 · отбор 10:20':'Проба ещё не зарегистрирована'}${s.temperature?' · подготовка: 20,2 °C':''}</p></section>`;}
    function header(){return `<header class="lab-header"><div><h1>Лаборатория качества</h1><p>От первой пробы до решения по партии</p></div><span class="lab-duration">${icon('clock')}8–12 минут · в твоём темпе</span></header>${s.started?`<nav class="lab-phases" aria-label="Этапы лаборатории">${phases.map((name,i)=>`<button type="button" data-do="lab-phase" data-value="${i}" class="${i===s.phase?'is-current':''} ${i<s.unlocked||s.done?'is-done':''}" ${i===s.phase?'aria-current="step"':''} ${i>s.unlocked?'disabled':''}><span>${i<s.unlocked||s.done?icon('check'):i+1}</span><span>${name}</span></button>`).join('')}</nav><div class="lab-context"><div>${icon('flask')}<span>Партия <strong>P-214</strong><span class="lab-context-detail"> · T-07${s.registered?' · L-041':''}</span></span></div><span class="lab-batch-status ${s.assessed?'is-held':''}">${s.assessed?icon('alert'):'<i></i>'}${s.assessed?'Удерживается':'Ожидает проверки'}</span>${btn('lab-journal',icon('book')+'Журнал','lab-quiet')}</div>${journalOpen?journal():''}`:''}`;}
    function welcome(){
      const tours={receiving:['Приём проб','В лабораторию поступают пробы воды, сырья, напитка в процессе и готовой продукции. Каждая связана с источником, временем и задачей проверки.'],bench:['Исследования','Лаборант готовит пробу, проверяет приборы и выполняет исследования по методике. Достоверный результат начинается до нажатия кнопки «Измерить».'],data:['Результаты и команда','Лаборатория сохраняет данные, специалист качества оценивает соответствие, технолог проверяет процесс. Вместе они определяют дальнейшие действия.']};
      return `<div class="lab-panorama"><img src="assets/lab-interior-v1.png" alt="Учебная иллюстрация лаборатории напитков: приёмка слева, приборы на центральном столе, рабочее место наставника справа" width="1536" height="1024" fetchpriority="high"><div class="lab-hotspots">${[['receiving','Приём проб'],['bench','Исследования'],['data','Результаты']].map(([id,title])=>`<button type="button" data-do="lab-tour" data-value="${id}" class="lab-hotspot lab-hotspot--${id}" aria-label="${title}" aria-expanded="${tour===id}">${icon(id==='receiving'?'flask':id==='bench'?'drop':'book')}<span>${title}</span></button>`).join('')}</div></div>${tour?`<div class="lab-tour-note"><strong>${tours[tour][0]}</strong><p>${tours[tour][1]}</p></div>`:'<p class="lab-art-caption">Учебная иллюстрация · загляни в рабочие зоны или начни смену</p>'}<div class="lab-welcome-bottom"><div><h2 class="lab-stage-title" tabindex="-1">Маленькая проба. Большая ответственность.</h2><p>Пройди путь стажёра: прими образец, исследуй напиток и передай команде проверенные данные. Наставник будет рядом.</p></div>${primary('lab-start','Принять пробу')}</div>`;
    }
    function receipt(){
      const docs={label:['Этикетка пробы','Основа безалкогольного напитка','P-214','Ёмкость T-07','Отбор 10:20 · оператор участка'],direction:['Направление на исследование','До насыщения газом и розлива','P-214','Ёмкость T-07','Исследования: pH и °Brix'],seal:['Осмотр ёмкости','Ёмкость закрыта, крышка цела','P-214','Следов протечки нет','Условия доставки по учебной карточке соблюдены']}[doc];
      return `<div class="lab-work-grid"><section class="lab-receiving-scene"><div class="lab-scene-top"><span>Приёмный стол</span><span>10:26</span></div><div class="lab-receiving-objects">${vessel(s.registered?'L-041':'P-214')}<div class="lab-paper"><span class="lab-paper-type">${docs[0]}</span><strong>${docs[2]}</strong><p>${docs[1]}</p><dl><div><dt>Источник</dt><dd>${docs[3]}</dd></div><div><dt>Сведения</dt><dd>${docs[4]}</dd></div></dl><span class="lab-paper-mark">${s.inspected.includes(doc)?icon('check')+'Проверено':'К проверке'}</span></div></div><div class="lab-inspect-tabs" role="group" aria-label="Осмотр основной пробы">${[['label','Этикетка'],['direction','Направление'],['seal','Крышка']].map(([id,text])=>`<button type="button" data-do="lab-inspect" data-value="${id}" class="${doc===id?'is-current':''}" aria-pressed="${doc===id}">${s.inspected.includes(id)?icon('check'):icon('info')}${text}</button>`).join('')}</div><p class="lab-caption">Нажми на каждый документ и осмотри ёмкость.</p></section><section class="lab-task"><h2 class="lab-stage-title" tabindex="-1">Сначала — происхождение</h2><p>Сверь партию и источник с направлением. Без этой связи результат нельзя отнести к нужному напитку.</p>${mentor('Проверь этикетку, направление и крышку. У второй ёмкости источник не читается — как с ней поступим?')}<div class="lab-secondary-sample"><span>${icon('flask')}Отдельная проба · источник не читается</span><div class="lab-choices" role="group" aria-label="Решение по отдельной пробе">${choice('lab-unknown','clarify','Запросить источник отбора','Оставить закрытой до уточнения',s.unknown==='clarify')}${choice('lab-unknown','guess','Указать T-07, как у соседней пробы')}${choice('lab-unknown','test','Исследовать без источника')}</div></div>${note()}<div class="lab-task-footer"><span>${s.registered?'Проба L-041 зарегистрирована':`${s.inspected.length} из 3 проверок · ${s.unknown==='clarify'?'источник второй пробы запрошен':'уточни вторую пробу'}`}</span>${primary('lab-register',s.registered?'К подготовке':'Зарегистрировать пробу',!receiptReady()&&!s.registered)}</div></section></div>`;
    }
    function preparation(){
      const steps=[['temperature','Температура по методике'],['mixed','Аккуратное перемешивание'],['portions','Две подписанные порции'],['controlPh','Контроль pH-метра'],['controlBx','Контроль рефрактометра']];
      let task;
      if(!s.temperature)task=`<h2 class="lab-stage-title" tabindex="-1">Подготовь пробу к работе</h2><p>Температура образца — 24,3 °C. В этой учебной методике исследования выполняются при 19–21 °C.</p><div class="lab-choices">${btn('lab-temp-wrong','Измерить при текущей температуре','lab-outline')}${btn('lab-dilute','Разбавить водой для измерения','lab-outline')}</div>${mentor('Подготовка должна сохранить свойства пробы и создать условия, заданные методикой.')}${note()}${primary('lab-condition','Подготовить по методике')}`;
      else if(!s.mixed)task=`<h2 class="lab-stage-title" tabindex="-1">Сделай пробу однородной</h2><p>Температура — 20,2 °C. Теперь аккуратно перемешай пробу, не разбавляя и не вспенивая её.</p>${mentor('Мы исследуем часть образца. Она должна отражать состав подготовленной пробы.')}${note()}${primary('lab-mix','Аккуратно перемешать')}`;
      else if(!s.portions)task=`<h2 class="lab-stage-title" tabindex="-1">Для каждого исследования — своя порция</h2><p>Подготовь две чистые ёмкости. Их обозначения сохранят связь с L-041: одна для pH, другая для °Brix.</p>${mentor('Использованный образец не возвращаем в исходную ёмкость. Работаем с отдельными порциями.')}${note()}${primary('lab-portions','Подготовить две порции')}`;
      else task=`<h2 class="lab-stage-title" tabindex="-1">Убедись, что приборам можно доверять</h2><p>Калибровку ранее выполнил наставник. Проверь оба прибора по контрольным материалам с известными значениями.</p><div class="lab-control-tests">${btn('lab-control-ph',`${icon(s.controlPh?'check':'drop')}<span>pH-метр<strong>${s.controlPh?'4,01 · проверка пройдена':'Контрольный материал pH 4,01'}</strong></span>`,s.controlPh?'is-checked':'lab-outline','',s.controlPh)}${btn('lab-control-bx',`${icon(s.controlBx?'check':'drop')}<span>Рефрактометр<strong>${s.controlBx?'10,0 °Bx · проверка пройдена':'Контрольный материал 10,0 °Bx'}</strong></span>`,s.controlBx?'is-checked':'lab-outline','',s.controlBx)}</div>${mentor('Проверка подтверждает готовность прибора. Подгонять показание напитка под нужное число нельзя.')}${note()}${primary('lab-prepared','К исследованиям',!prepared())}`;
      return `<div class="lab-work-grid"><section class="lab-prep-scene"><div class="lab-scene-top"><span>Подготовка L-041</span><span>Учебная методика</span></div><div class="lab-prep-objects ${s.mixed?'is-mixed':''}">${vessel()}${s.portions?'<div class="lab-aliquots"><div><span class="lab-mini-beaker"></span><strong>L-041 · pH</strong></div><div><span class="lab-mini-beaker"></span><strong>L-041 · °Bx</strong></div></div>':`<div class="lab-temperature"><span>Температура пробы</span><strong class="lab-num">${s.temperature?'20,2':'24,3'}<small>°C</small></strong><span>${s.temperature?'В условиях методики':'Нужна подготовка'}</span></div>`}</div><ol class="lab-checklist">${steps.map(([key,title])=>`<li class="${s[key]?'is-complete':''}"><span>${s[key]?icon('check'):'<i></i>'}</span>${title}</li>`).join('')}</ol></section><section class="lab-task">${task}</section></div>`;
    }
    function measurement(){
      const m=s.metric,done=s[m+'Run'],saved=s[m+'Saved'],running=busy===m;
      const action=!s[m+'Clean']?['lab-clean',m==='ph'?'Подготовить электрод':'Подготовить поверхность']:!s[m+'Loaded']?['lab-load',m==='ph'?'Опустить в порцию L-041 · pH':'Нанести порцию L-041 · °Bx']:!done?['lab-measure','Начать измерение']:!saved?['lab-save-measure',`Сохранить ${valueFor(m)}${m==='bx'?' °Bx':''}`]:['lab-measured','К результатам'];
      const value=running?liveValue:done?valueFor(m):'—';
      return `<div class="lab-measure-tabs" role="group" aria-label="Выбор исследования">${[['ph','pH-метр'],['bx','Рефрактометр']].map(([id,title])=>`<button type="button" data-do="lab-metric" data-value="${id}" class="${m===id?'is-current':''}" aria-pressed="${m===id}" ${busy?'disabled':''}>${s[id+'Saved']?icon('check'):icon('drop')}<span>${title}<small>${s[id+'Saved']?'Результат сохранён':id==='ph'?'Кислотные свойства':'Шкала °Brix'}</small></span></button>`).join('')}</div><div class="lab-work-grid"><section class="lab-instrument-scene ${running?'is-measuring':''}"><div class="lab-scene-top"><span>${m==='ph'?'pH-метр':'Цифровой рефрактометр'}</span><span>L-041 · ${labelFor(m)}</span></div>${instrument(m,s)}<div class="lab-readout"><div><span>${running?'Показание устанавливается':done?'Стабильный результат':'Ожидание исследования'}</span><output class="lab-num">${value}${m==='bx'&&value!=='—'?'<small>°Bx</small>':''}</output></div><span class="lab-instrument-status ${done?'is-ready':''}">${done?icon('check'):icon('clock')}${saved?'В журнале':done?'Стабильно':s[m+'Loaded']?'Проба установлена':s[m+'Clean']?'Прибор подготовлен':'Подготовь прибор'}</span></div></section><section class="lab-task"><h2 class="lab-stage-title" tabindex="-1">${m==='ph'?'Измерь pH':'Исследуй раствор'}</h2><p>${m==='ph'?'pH связан с кислотными свойствами напитка. Меньшее значение означает более кислую среду.':'Рефрактометр измеряет преломление света. Результат по шкале °Brix зависит от растворённых веществ в напитке.'}</p><ol class="lab-checklist">${[[s[m+'Clean'],m==='ph'?'Промыть и подготовить электрод':'Очистить измерительную поверхность'],[s[m+'Loaded'],'Установить отдельную порцию'],[done,'Получить стабильное показание'],[saved,'Сохранить результат в журнале']].map(([on,text])=>`<li class="${on?'is-complete':''}"><span>${on?icon('check'):'<i></i>'}</span>${text}</li>`).join('')}</ol>${mentor(running?'Показание ещё меняется. Сохраняем только после отметки стабильности.':m==='ph'?'Промывка помогает не перенести остатки предыдущего раствора в пробу.':'На поверхности не должно остаться контрольного раствора: он изменит показание.')}<details class="lab-detail"><summary>${m==='ph'?'pH — это кислотность?':'°Brix — это содержание сахара?'}</summary><p>${m==='ph'?'pH и общая, или титруемая, кислотность — разные показатели. Здесь мы измеряем именно pH.':'На показание влияют разные растворённые вещества. °Brix не равен отдельному измерению чистого сахара и не является плотностью.'}</p></details>${note()}<div class="lab-task-footer">${running?`${btn('lab-early','Сохранить текущее число','lab-outline')}${primary('lab-finish-run','Показать стабильный результат')}`:primary(action[0],action[1],action[0]==='lab-measured'&&!(s.phSaved&&s.bxSaved))}${!s[m+'Clean']?btn('lab-skip-clean','Установить пробу сразу','lab-quiet'):''}</div><p class="lab-caption">${s.phSaved&&s.bxSaved?'Оба результата в журнале. Пора проверить соответствие.':'Сохрани оба исследования, чтобы перейти к результатам.'}</p></section></div>${journal()}`;
    }
    function gauge(title,value,min,max,low,high,m){
      return `<div class="lab-gauge"><div class="lab-section-row"><strong>${title}</strong><span class="lab-num">${String(value).replace('.',',')}${m==='bx'?' °Bx':''}</span></div><div class="lab-gauge-track"><span class="lab-gauge-range" style="left:${(low-min)/(max-min)*100}%;width:${(high-low)/(max-min)*100}%"></span><span class="lab-gauge-point" style="left:${(value-min)/(max-min)*100}%"></span></div><div class="lab-gauge-labels"><span>${String(min).replace('.',',')}</span><span>Учебный диапазон ${m==='ph'?'3,00–3,40':'9,8–10,2 °Bx'}</span><span>${String(max).replace('.',',')}</span></div></div>`;
    }
    function results(){return `<div class="lab-work-grid"><section class="lab-results-sheet"><div class="lab-section-row"><h3>Результаты L-041</h3>${icon('book')}</div><p>Основа напитка · до насыщения газом</p>${gauge('pH',3.21,2.8,3.6,3,3.4,'ph')}${gauge('Показание °Brix',9.2,8.8,10.8,9.8,10.2,'bx')}<div class="lab-requirements"><strong>Требования к учебной пробе</strong><p>pH: 3,00–3,40<br>°Brix: 9,8–10,2 °Bx</p><span>Подготовка: 20,2 °C</span></div><p class="lab-caption">Учебные значения. Реальные требования зависят от напитка и утверждённой методики.</p></section><section class="lab-task"><h2 class="lab-stage-title" tabindex="-1">Что говорят результаты?</h2><fieldset class="lab-field"><legend>Выбери требования</legend>${choice('lab-requirement','base','Основа напитка','До насыщения газом',s.requirement==='base')}${choice('lab-requirement','other','Готовый продукт','Другая рецептура',s.requirement==='other')}</fieldset><fieldset class="lab-field"><legend>pH · 3,21</legend><div class="lab-segments">${[['in','В диапазоне'],['below','Ниже'],['above','Выше']].map(([id,title])=>btn('lab-verdict-ph',title,s.verdictPh===id?'is-selected':'',id)).join('')}</div></fieldset><fieldset class="lab-field"><legend>°Brix · 9,2 °Bx</legend><div class="lab-segments">${[['in','В диапазоне'],['below','Ниже'],['above','Выше']].map(([id,title])=>btn('lab-verdict-bx',title,s.verdictBx===id?'is-selected':'',id)).join('')}</div></fieldset><fieldset class="lab-field"><legend>Какой вывод подтверждают данные?</legend>${choice('lab-finding','fact','°Bx ниже диапазона, причина неизвестна','Нужно проверить отклонение',s.finding==='fact')}${choice('lab-finding','water','Оператор точно добавил лишнюю воду','Причина уже известна',s.finding==='water')}${choice('lab-finding','ph','pH в норме — можно продолжать','',s.finding==='ph')}</fieldset>${note()}${primary('lab-assess',s.assessed?'К проверке отклонения':'Зафиксировать оценку')}</section></div>`;}
    function deviation(){
      let task,scene;
      if(!s.messageSent)task=`<h2 class="lab-stage-title" tabindex="-1">Передай факты команде</h2><p>Наставник уже сообщил об отклонении. P-214 удерживается до решения службы качества. Дополни сообщение данными исследования.</p><div class="lab-choices">${choice('lab-notification','facts','Партия, источник и результаты','P-214 · T-07 · L-041. °Bx: 9,2 при диапазоне 9,8–10,2. pH: 3,21. Условия проверены; причина неизвестна.',s.notification==='facts')}${choice('lab-notification','vague','«Напиток плохой, посмотрите»','Без номера партии и значений',s.notification==='vague')}${choice('lab-notification','blame','«Это ошибка оператора»','Сразу назвать виновного',s.notification==='blame')}</div>${note()}${primary('lab-send','Передать данные команде')}`;
      else if(!s.reviewed)task=`<h2 class="lab-stage-title" tabindex="-1">Проверь, сохраняя исходное</h2><p>Специалист качества назначает проверку. Как действовать с результатом 9,2 °Bx?</p><div class="lab-choices">${choice('lab-plan','review','Проверить условия и записи','Затем повторить на новой порции, сохранив исходный результат',s.plan==='review')}${choice('lab-plan','erase','Удалить и измерять до нужной цифры','Оставить только подходящее значение',s.plan==='erase')}${choice('lab-plan','syrup','Добавить сироп в лабораторную пробу','Исправить число прямо в ёмкости',s.plan==='syrup')}</div>${note()}${primary('lab-review','Проверить записи и условия')}`;
      else{
        const action=!s.repeatPortion?['lab-repeat-portion','Подготовить новую порцию']:!s.repeatClean?['lab-repeat-clean','Подготовить рефрактометр']:!s.repeatRun?['lab-repeat-run','Провести назначенный повтор']:!s.repeatSaved?['lab-repeat-save','Сохранить повтор отдельной строкой']:['lab-to-handover','К заключению'];
        task=`<h2 class="lab-stage-title" tabindex="-1">${s.repeatSaved?'Отклонение сохраняется':'Повторная проверка'}</h2><p>${s.repeatSaved?'Повтор дал 9,2 °Bx. Исходный результат сохранён. Оснований снять удержание пока нет.':'Используем новую порцию из исходной пробы L-041. Это повторное исследование, а не новый отбор из ёмкости T-07.'}</p><ol class="lab-checklist">${[[s.repeatPortion,'Новая порция L-041'],[s.repeatClean,'Прибор подготовлен'],[s.repeatRun,'Повтор выполнен'],[s.repeatSaved,'Отдельная запись сохранена']].map(([on,title])=>`<li class="${on?'is-complete':''}"><span>${on?icon('check'):'<i></i>'}</span>${title}</li>`).join('')}</ol>${mentor(s.repeatSaved?'Проверяю записи дозирования, приготовления, перемешивания и точку отбора. Одно отклонение ещё не доказывает его причину.':'Проверили подготовку и контроль прибора. Выполняем повтор по согласованной учебной процедуре.',s.repeatSaved?'Технолог':'Специалист качества')}<details class="lab-detail"><summary>А если повтор оказался бы в диапазоне?</summary><p>Это не отменяет первый результат автоматически. Расхождение нужно объяснить и оценить по принятому порядку; удержание снимает уполномоченный специалист.</p></details>${note()}${busy?primary('lab-finish-run','Показать результат повтора'):primary(action[0],action[1])}`;
      }
      if(s.reviewed)scene=`<section class="lab-instrument-scene ${busy?'is-measuring':''}"><div class="lab-scene-top"><span>Назначенная проверка</span><span>L-041 · повтор</span></div>${instrument('bx',s,true)}<div class="lab-readout"><div><span>${s.repeatRun?'Результат повтора':'Новая порция исходной пробы'}</span><output class="lab-num">${s.repeatRun?'9,2<small>°Bx</small>':busy?'…':'—'}</output></div><span>${s.repeatSaved?'Сохранён отдельно':s.repeatRun?'Стабильно':'Повтор'}</span></div>${s.repeatSaved?'<div class="lab-original-pair"><span>Исходный <strong>9,2 °Bx</strong></span><span>Повтор <strong>9,2 °Bx</strong></span></div>':''}</section>`;
      else scene=`<section class="lab-team-scene"><div class="lab-scene-top"><span>Связь с производством</span><span>Учебная сцена</span></div><div class="lab-production-path"><div class="lab-tank"><i></i><strong>T-07</strong><span>P-214</span></div><div class="lab-hold-gate">${icon('alert')}<strong>Удерживается</strong><span>До решения службы качества</span></div></div><div class="lab-team-messages">${mentor('P-214 дальше не передаю. Жду решение ответственного специалиста.','Оператор участка')}${mentor(s.messageSent?'Данные получил. Проверю записи приготовления и точку отбора.':'Какая партия, источник и результат? Проверены ли прибор и подготовка?','Технолог')}${s.messageSent?mentor('Исходный результат сохраняем. Сначала проверим записи и условия, затем выполним назначенный повтор.','Специалист качества'):''}</div></section>`;
      return `<div class="lab-hold-notice">${icon('alert')}<p><strong>Отклонение уже передано ответственным.</strong> Удержание P-214 действует до повторной проверки и после неё — до решения специалиста.</p></div><div class="lab-work-grid">${scene}<section class="lab-task">${task}</section></div>${s.repeatSaved?journal():''}`;
    }
    function handover(){
      if(s.done)return `<section class="lab-completed"><div class="lab-completed-scene"><img src="assets/lab-interior-v1.png" alt="Лаборатория продолжает работу после передачи результатов" width="1536" height="1024"><span>${icon('check')}Запись принята наставником</span></div><div class="lab-completed-copy"><h2 class="lab-stage-title" tabindex="-1">Данные переданы.<br>Проверка продолжается.</h2><p>Ты сохранил связь с пробой, заметил отклонение и передал команде данные, по которым можно действовать.</p><div class="lab-final-facts"><span>${icon('check')}Проба зарегистрирована</span><span>${icon('check')}Два исследования сохранены</span><span>${icon('check')}Повтор записан отдельно</span><span>${icon('check')}Отклонение передано</span></div>${mentor('Результат смены — не всегда готовая отгрузка. Сегодня ты вовремя заметил то, что нужно проверить.','Огонёк')}<p class="lab-caption">P-214 остаётся на удержании. Учебная задача стажёра завершена.</p>${primary('finish','Записать открытие')}${btn('lab-restart','Повторить лабораторию','lab-quiet')}</div></section>`;
      return `<div class="lab-work-grid"><section class="lab-handover-sheet"><div class="lab-section-row"><h3>Карточка передачи</h3>${icon('book')}</div><strong class="lab-report-id">L-041</strong><p>P-214 · T-07 · основа напитка</p><dl><div><dt>Подготовка</dt><dd>По учебной методике · 20,2 °C</dd></div><div><dt>pH</dt><dd>3,21 · в диапазоне</dd></div><div><dt>°Brix · исходный</dt><dd>9,2 °Bx · ниже диапазона</dd></div><div><dt>°Brix · повтор</dt><dd>9,2 °Bx · отдельная запись</dd></div><div><dt>Причина</dt><dd>Пока не установлена</dd></div><div><dt>Дальше</dt><dd>Оценка отклонения с технологом</dd></div></dl><div class="lab-report-stamp">${icon('alert')}Удержание партии сохраняется</div></section><section class="lab-task"><h2 class="lab-stage-title" tabindex="-1">Оформи заключение</h2><p>Все результаты связаны с пробой. Какое решение ты передашь наставнику?</p><div class="lab-choices">${choice('lab-decision','hold','Передать специалисту качества','Удержание партии сохранить',s.decision==='hold')}${choice('lab-decision','release','Разрешить дальнейшее производство','Партия полностью соответствует',s.decision==='release')}${choice('lab-decision','scrap','Сразу уничтожить партию','Окончательно решить её судьбу',s.decision==='scrap')}</div>${mentor('Стажёр передаёт проверенные данные. Дальнейшее обращение с партией определяет уполномоченный специалист.','Специалист качества')}<details class="lab-detail"><summary>Что происходит после передачи?</summary><p>Специалист качества и технолог проверяют достоверность данных и разбирают процесс. Могут понадобиться дополнительные исследования или новый отбор. Разрешённую корректировку выполняет производство, после неё проводят необходимый контроль. Затем ответственные сотрудники принимают решение по партии.</p></details>${note()}${primary('lab-handover','Передать запись наставнику')}<p class="lab-caption">Только в учебной сцене. Сообщение не отправляется за пределы игры.</p></section></div>`;
    }
    function render(){
      if(disposed)return;
      const active=document.activeElement,focus=active&&a.content.contains(active)?{action:active.dataset.do,value:active.dataset.value}:null;
      a.content.innerHTML=`${header()}${s.started?[receipt,preparation,measurement,results,deviation,handover][s.phase]():welcome()}${s.started?help():''}<details class="lab-about"><summary>О работе лаборатории и этой учебной модели</summary><p>Пробы проходят регистрацию, подготовку, исследования, запись результатов и оценку соответствия. Лаборанты работают с методиками и приборами; специалисты качества и технологи оценивают отклонения и дальнейшие действия. Интерьер, ситуация и числовые диапазоны здесь вымышлены.</p><div class="lab-more-topics"><details><summary>Микробиологический контроль</summary><p>У него отдельные условия, подготовка и время выполнения. Результаты не появляются мгновенно; использованная порция после pH-метра не становится подходящей микробиологической пробой.</p></details><details><summary>Оценка вкуса и аромата</summary><p>Обученные специалисты оценивают заданные характеристики напитка. Это дополняет измерения и не заменяет лабораторный контроль. Неизвестные лабораторные пробы не дегустируют.</p></details><details><summary>Правильный отбор</summary><p>Источник, время, способ отбора и доставка влияют на то, насколько проба отражает состояние партии. Представительность не определяется одним размером ёмкости.</p></details></div></details>`;
      if(s.started){
        a.content.querySelectorAll('.lab-phases button').forEach((node,index)=>node.setAttribute('aria-label',`${phases[index]} · этап ${index+1} из 6${index>s.unlocked?' · сначала заверши предыдущие этапы':''}`));
        const summary=document.createElement('p');
        summary.className='lab-mobile-phase';
        summary.innerHTML=`${phases[s.phase]}<span>Этап ${s.phase+1} из 6</span>`;
        a.content.querySelector('.lab-phases').after(summary);
      }
      if(s.assessed&&s.phase===3)a.content.querySelectorAll('[data-do="lab-requirement"],[data-do="lab-verdict-ph"],[data-do="lab-verdict-bx"],[data-do="lab-finding"]').forEach(node=>node.disabled=true);
      if(focus?.action)[...a.content.querySelectorAll('[data-do]')].find(n=>n.dataset.do===focus.action&&n.dataset.value===focus.value&&!n.disabled)?.focus({preventScroll:true});
    }
    function run(metric){
      if(busy||disposed)return;
      busy=metric;liveValue=metric==='ph'?'3,18':'…';render();
      if(window.matchMedia('(prefers-reduced-motion: reduce)').matches||window.GameMotion?.enabled()===false){finishRun();return;}
      if(metric==='ph')timers.add(setTimeout(()=>{if(!disposed&&busy==='ph'){liveValue='3,24';render();}},650));
      timers.add(setTimeout(finishRun,1500));
    }
    function finishRun(){
      if(!busy||disposed)return;
      const m=busy;busy='';timers.forEach(clearTimeout);timers.clear();
      if(m==='repeat')s.repeatRun=true;else s[m+'Run']=true;
      tell(m==='repeat'?'Повтор: 9,2 °Bx. Сохрани его отдельной записью.':'Стабильный результат получен. Теперь сохрани его в журнале.','success');save();render();
    }
    function act(type,value){
      if(type==='lab-journal'){journalOpen=!journalOpen;render();return;}
      if(type==='lab-tour'){if(['receiving','bench','data'].includes(value))tour=tour===value?'':value;render();return;}
      if(type==='lab-hint'){hint=Math.min(2,hint+1);render();return;}
      if(type==='lab-phase'){const p=Number(value);if(!busy&&Number.isInteger(p)&&p>=0&&p<=s.unlocked)move(p);return;}
      if(type==='lab-finish-run'){finishRun();return;}
      if(type==='lab-early'&&busy){tell('Показание ещё меняется. Дождись отметки стабильности или покажи стабильный результат.','error');render();return;}
      if(type==='lab-start'){s.started=true;move(0);return;}
      if(type==='lab-restart'&&s.done){s=fresh();move(0);return;}
      if(busy)return;
      if(s.phase===0){
        if(type==='lab-inspect'&&['label','direction','seal'].includes(value)){doc=value;if(!s.inspected.includes(value))s.inspected.push(value);tell(value==='seal'?'Ёмкость закрыта, крышка цела. Условия доставки соблюдены.':'Партия P-214 и источник T-07 совпадают с направлением.','success');}
        if(type==='lab-unknown'){if(value==='clarify'){s.unknown='clarify';tell('Источник запрошен у оператора. Отдельная ёмкость остаётся закрытой в зоне уточнения.','success');}else tell(value==='guess'?'Соседние ёмкости могут относиться к разным партиям. Источник нельзя назначать предположением.':'Без подтверждённого источника результат нельзя надёжно связать с партией. Сначала уточним происхождение.','error');}
        if(type==='lab-register'&&(receiptReady()||s.registered)){s.registered=true;move(1);return;}
      }else if(s.phase===1){
        if(type==='lab-condition'){s.temperature=true;tell('Проба подготовлена: 20,2 °C. Время подготовки сокращено для игры.','success');}
        if(type==='lab-temp-wrong')tell('24,3 °C вне условий учебной методики. Сначала приведи пробу к температуре 19–21 °C.','error');
        if(type==='lab-dilute')tell('Добавление воды изменит состав пробы. Для этой методики разбавление не предусмотрено.','error');
        if(type==='lab-mix'&&s.temperature){s.mixed=true;tell('Проба аккуратно перемешана. Подготовь отдельные порции.','success');}
        if(type==='lab-portions'&&s.mixed){s.portions=true;tell('Порции L-041 · pH и L-041 · °Bx подготовлены. Проверь готовность обоих приборов.','success');}
        if(type==='lab-control-ph'&&s.portions){s.controlPh=true;tell('Контроль pH-метра: 4,01. Учебная проверка пройдена.','success');}
        if(type==='lab-control-bx'&&s.portions){s.controlBx=true;tell('Контроль рефрактометра: 10,0 °Bx. Учебная проверка пройдена.','success');}
        if(type==='lab-prepared'&&prepared()){move(2);return;}
      }else if(s.phase===2){
        const m=s.metric;
        if(type==='lab-metric'&&['ph','bx'].includes(value)){s.metric=value;message='';}
        if(type==='lab-clean'){s[m+'Clean']=true;tell(m==='ph'?'Электрод подготовлен. Промывка предотвращает перенос остатков.':'Измерительная поверхность очищена от контрольного раствора.','success');}
        if(type==='lab-skip-clean')tell(m==='ph'?'Сначала подготовь электрод, чтобы не перенести остатки предыдущего раствора в пробу.':'На призме остался контрольный раствор. Сначала очисти поверхность.','error');
        if(type==='lab-load'&&s[m+'Clean']){s[m+'Loaded']=true;tell('Отдельная порция L-041 установлена. Можно начать измерение.','success');}
        if(type==='lab-measure'&&s[m+'Loaded']){run(m);return;}
        if(type==='lab-save-measure'&&s[m+'Run']){s[m+'Saved']=true;tell(`${labelFor(m)}: ${valueFor(m)}${m==='bx'?' °Bx':''} сохранён в журнале. ${m==='ph'?'Электрод промыт и возвращён в место хранения.':''}`,'success');if(m==='ph'&&!s.bxSaved)s.metric='bx';else if(m==='bx'&&!s.phSaved)s.metric='ph';}
        if(type==='lab-measured'&&s.phSaved&&s.bxSaved){move(3);return;}
      }else if(s.phase===3){
        const setters={'lab-requirement':'requirement','lab-verdict-ph':'verdictPh','lab-verdict-bx':'verdictBx','lab-finding':'finding'};
        if(setters[type]&&!s.assessed){s[setters[type]]=value;message='';}
        if(type==='lab-assess'){
          if(s.assessed){move(4);return;}
          if(s.requirement!=='base')tell('Выбери требования к основе напитка до насыщения газом. Другая рецептура к этой пробе не относится.','error');
          else if(s.verdictPh!=='in')tell('3,21 находится между 3,00 и 3,40. По pH отклонения нет.','error');
          else if(s.verdictBx!=='below')tell('9,2 °Bx ниже нижней границы 9,8. Мы фиксируем отклонение, а не расширяем диапазон на глаз.','error');
          else if(s.finding!=='fact')tell(s.finding==='water'?'Лишняя вода — гипотеза. По этим данным нельзя установить причину или обвинить оператора.':'Один подходящий показатель не отменяет отклонение другого. Причину ещё нужно выяснить.','error');
          else{s.assessed=true;move(4);tell('Наставник сразу уведомил ответственных. Оператор подтвердил удержание P-214 до решения службы качества.','success');render();return;}
        }
      }else if(s.phase===4){
        if(type==='lab-notification'&&!s.messageSent){s.notification=value;message='';}
        if(type==='lab-send'){if(s.notification==='facts'){s.messageSent=true;tell('Технолог получил партию, источник и оба результата. Проверит записи приготовления.','success');}else tell(s.notification==='blame'?'У нас есть отклонение, но не установленная причина. Передай наблюдение без обвинения.':'Сообщению нужны номер партии, источник, показатель и результат. Эти данные уже есть в журнале.','error');}
        if(type==='lab-plan'&&!s.reviewed){s.plan=value;message='';}
        if(type==='lab-review'){if(s.plan==='review'){s.reviewed=true;tell('Записи подготовки и контроль прибора проверены. Специалист назначил повтор на новой порции той же пробы.','success');}else tell(s.plan==='syrup'?'Сироп изменит пробу, но не производственную партию. Корректировка процесса требует согласованного решения.':'Исходный результат сохраняется. Повтор нужен для проверки, а не для поиска удобной цифры.','error');}
        if(type==='lab-repeat-portion'&&s.reviewed){s.repeatPortion=true;tell('Новая порция L-041 подготовлена. Это не новый отбор из производства.','success');}
        if(type==='lab-repeat-clean'&&s.repeatPortion){s.repeatClean=true;tell('Прибор подготовлен к повторному исследованию.','success');}
        if(type==='lab-repeat-run'&&s.repeatClean){run('repeat');return;}
        if(type==='lab-repeat-save'&&s.repeatRun){s.repeatSaved=true;tell('Повтор 9,2 °Bx добавлен отдельной записью. Исходный результат не изменён.','success');}
        if(type==='lab-to-handover'&&s.repeatSaved){move(5);return;}
      }else if(s.phase===5){
        if(type==='lab-decision'&&!s.done){s.decision=value;message='';}
        if(type==='lab-handover'){if(s.decision==='hold'){s.done=true;tell('Запись принята наставником. Удержание партии сохраняется.','success');}else tell(s.decision==='scrap'?'Дальнейшую судьбу партии определяют ответственные специалисты после оценки ситуации. Стажёр передаёт результаты.':'По °Bx сохраняется отклонение. Два учебных исследования не заменяют всю программу контроля и не разрешают выпуск партии.','error');}
      }
      save();render();illustrate(type);
    }
    function illustrate(type){
      if(window.matchMedia('(prefers-reduced-motion: reduce)').matches||window.GameMotion?.enabled()===false||document.hidden)return;
      let target,frames;
      if(type==='lab-load'&&s.metric==='ph'){target='.lab-electrode';frames=[{transform:'translateY(-35px)'},{transform:'translateY(0)'}];}
      if(type==='lab-load'&&s.metric==='bx'||type==='lab-repeat-portion'){target='.lab-pipette';frames=[{transform:'translate(22px,-22px)'},{transform:'translate(0,12px)',offset:.55},{transform:'translate(18px,-8px)'}];}
      if(type==='lab-mix'){target='.lab-vessel';frames=[{transform:'rotate(0)'},{transform:'rotate(-4deg)'},{transform:'rotate(4deg)'},{transform:'rotate(0)'}];}
      if(type==='lab-condition'){target='.lab-temperature';frames=[{opacity:.4},{opacity:1}];}
      if(type==='lab-inspect'){target='.lab-paper';frames=[{opacity:.6},{opacity:1}];}
      if(target)a.content.querySelector(target)?.animate(frames,{duration:type==='lab-inspect'?250:700,easing:'ease-in-out'});
    }
    function onMotion(e){if(!e.detail.enabled){a.root.getAnimations({subtree:true}).forEach(animation=>animation.cancel());if(busy)finishRun();}}
    document.addEventListener('ochakovo:motion',onMotion);
    return{start(){save();render();},done:()=>s.done,act,cleanup(){disposed=true;timers.forEach(clearTimeout);timers.clear();document.removeEventListener('ochakovo:motion',onMotion);}};
  });
})();
